// odds of one ticket winning a 6-of-49 lottery
let count = 1;
for (let i = 0; i < 6; i++) {
  count *= 49 - i;            // 49 * 48 * 47 * 46 * 45 * 44
}
console.log("1 in", count);   // 1 in 10,068,347,520
// published odds: 1 in 13,983,816 — who is wrong?

